{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C26","C32","C33","C17","C34","C31","C53","C44","C42","C48","C47","C46","C43","C54","C57","C58","C60","C61","C62","C64"],
  "contradictory_card_ids": ["C19"],
  "prediction_basis_card_ids": ["C26","C33","C17","C53","C44","C54","C58","C62","C64"],
  "claims": [
    {
      "claim": "Ketoconazole, a close structural analog sharing the dioxolane-dichlorophenyl-piperazine-aryl ether azole core, has measured absolute oral bioavailability of 0.56 ± 0.23 in dogs (C33) and approximately 75% in healthy volunteers (C26, C32), affirmatively supporting F ≥ 20% for the query.",
      "card_ids": ["C33","C26","C32"]
    },
    {
      "claim": "Fluconazole, another azole antifungal, has absolute oral bioavailability >90% in normal volunteers (C17), 103.4% via jejunostomy (C34), and 97.2% in ICU patients without rifampin (C31), all well above the 20% threshold.",
      "card_ids": ["C17","C34","C31"]
    },
    {
      "claim": "L3 oral exposure records for posaconazole (M01), a close structural analog, show substantial oral absorption/exposure (e.g., Cmax 851 ng/mL and AUC 8619 ng·h/mL at steady state after 400 mg oral suspension BID, C44/C53; Cmax 605–607 ng/mL after a single 400 mg dose with a high-fat meal, C42/C48; AUCt 2976 ng·h/mL after 200 mg with antacid, C47), and for ketoconazole (M02) measurable steady-state AUC (C43); these are consistent with, but do not directly prove, F ≥ 20%.",
      "card_ids": ["C53","C44","C42","C48","C47","C43"]
    },
    {
      "claim": "L4 permeability records for posaconazole show consistently high Caco-2 permeability (3.4–4.0 ×10^-5 cm/s; C54, C58, C60, C61, C64; also C57/C62), with classification as low solubility–high permeability (C62), supporting that the azole-dioxolane/piperazine-aryl ether class can achieve sufficient absorption despite low solubility.",
      "card_ids": ["C54","C58","C60","C61","C64","C57","C62"]
    },
    {
      "claim": "Low solubility records (C55, C56, C63, C59, C65) are not affirmative F < 20% evidence; ketoconazole has poor aqueous solubility (0.04 mg/mL, C63) yet measured F ~75% in humans (C26) and 56% in dogs (C33), and posaconazole's low solubility is accompanied by high permeability (C62).",
      "card_ids": ["C63","C26","C33","C56","C62"]
    },
    {
      "claim": "The non-quantitative 'low oral bioavailability' statement for ketoconazole (C19) is outweighed by measured F values and does not affirm F < 20%.",
      "card_ids": ["C19"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C54","C55","C56","C57","C58","C60","C61","C62","C63","C64"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is present in the supplied cards.",
    "L4 permeability and solubility records are for posaconazole and ketoconazole, not the query; transfer is qualitative.",
    "L3 posaconazole exposure records lack matched IV comparators, so they cannot directly quantify F.",
    "No query-specific solubility, permeability, formulation, dose, prandial state, or first-pass clearance data are supplied.",
    "The unfavorable physicochemical prior is generic and not calibrated to the query's actual absorption or metabolism.",
    "Caco-2 permeability may not fully capture in vivo absorption for this large lipophilic molecule; solubility and formulation effects remain."
  ],
  "decision_summary": "Predicted high because close structural analogs ketoconazole and posaconazole show measured oral bioavailability/exposure and high permeability consistent with F ≥ 20%; new L4 permeability records strengthen the supportive evidence, and low solubility records do not affirm F < 20% for the query."
}

